import React, { useState } from "react";
import { supabase } from "./supabaseClient";
const ALL_ROADS_LOGO =
  "data:image/png;base64,";


export default function AccountingExports() {
  const today = new Date().toISOString().slice(0, 10);

  const [startDate, setStartDate] = useState(today);
  const [endDate, setEndDate] = useState(today);

  const [yardTickets, setYardTickets] = useState([]);
  const [loadingYardTickets, setLoadingYardTickets] = useState(false);

  function csvEscape(value) {
    const text = String(value ?? "");
    return `"${text.replace(/"/g, '""')}"`;
  }

  function downloadCsv(filename, rows) {
    const csv =
      "\uFEFF" + rows.map((row) => row.map(csvEscape).join(",")).join("\n");

    const blob = new Blob([csv], {
      type: "text/csv;charset=utf-8;",
    });

    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");

    link.href = url;
    link.download = filename;

    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);

    URL.revokeObjectURL(url);
  }

  function formatExportDate(value) {
    if (!value) return "";

    if (typeof value === "string" && /^\d{4}-\d{2}-\d{2}$/.test(value)) {
      return value;
    }

    const d = new Date(value);
    if (Number.isNaN(d.getTime())) return "";

    return d.toISOString().slice(0, 10);
  }

  function formatExportTime(value) {
    if (!value) return "";

    const d = new Date(value);
    if (Number.isNaN(d.getTime())) return "";

    return d.toLocaleTimeString("en-CA", {
      hour: "numeric",
      minute: "2-digit",
      hour12: true,
    });
  }

  function splitProduct(productName) {
    const text = String(productName || "").trim();

    const match = text.match(/^(\d+)\s*[-–]\s*(.+)$/);

    if (match) {
      return {
        code: match[1].trim(),
        description: match[2].trim(),
      };
    }

    return {
      code: "",
      description: text,
    };
  }

  function normalizeCustomerName(value) {
    return String(value || "")
      .toLowerCase()
      .replace(/&/g, "and")
      .replace(/\b(ltd|limited|inc|corp|corporation|co|company)\b/g, "")
      .replace(/[^a-z0-9]/g, "");
  }

  function findCustomerByName(ticketCustomerName, customersMasterRows) {
    const normalizedTicketCustomer = normalizeCustomerName(ticketCustomerName);

    if (!normalizedTicketCustomer) return null;

    const exactMatch = customersMasterRows.find((customer) => {
      const masterName = normalizeCustomerName(customer.customer_name);
      const masterNormalized = normalizeCustomerName(customer.normalized_name);

      return (
        masterName === normalizedTicketCustomer ||
        masterNormalized === normalizedTicketCustomer
      );
    });

    if (exactMatch) return exactMatch;

    const fuzzyMatch = customersMasterRows.find((customer) => {
      const masterName = normalizeCustomerName(customer.customer_name);
      const masterNormalized = normalizeCustomerName(customer.normalized_name);

      return (
        masterName.includes(normalizedTicketCustomer) ||
        normalizedTicketCustomer.includes(masterName) ||
        masterNormalized.includes(normalizedTicketCustomer) ||
        normalizedTicketCustomer.includes(masterNormalized)
      );
    });

    return fuzzyMatch || null;
  }

  function buildAccountingHeaders() {
    return [
      "Date",
      "Location",
      "Ticket",
      "Time",
      "Customer",
      "Customer Name",
      "Order",
      "Description",
      "Product",
      "Product Name",
      "Carrier Name",
      "Carrier",
      "Vehicle",
      "Vehicle Name",
      "Qty",
      "Unit",
      "Total Price",
      "Dispatch No.",
      "Dispatch Date",
      "Dispatch Load",
      "Void",
      "Material",
      "Freight",
      "Other",
      "Tax",
      "Zone",
      "Invoice ",
      "Item No",
      "Purchase Order",
      "Gross",
      "Tare",
      "Net",
      "Unit Price",
      "Freight Rate",
      "Tax Code",
      "Freight FOB",
      "Freight Pay",
      "Destination",
      "Destination Description",
      "Reference Ticket",
      "Today Loads",
      "Today Qty",
      " ",
      "Reason",
    ];
  }

  function validateRows(headers, rows) {
    const badRows = rows
      .map((row, index) => ({
        rowNumber: index + 1,
        count: row.length,
      }))
      .filter((row) => row.count !== headers.length);

    if (badRows.length) {
      console.error("Accounting export column mismatch:", {
        headerCount: headers.length,
        badRows,
      });

      throw new Error(
        `Export column mismatch. Header has ${headers.length} columns. Check console.`
      );
    }
  }

  function printAccountingYardTicket(ticket) {
  const copies = [
    "COPY 1 CARRIER",
    "COPY 2 CUSTOMER",
    "COPY 3 FILE",
  ];

  const html = copies
    .map(
      (copy) => `
      <div class="ticket">

  <div class="header">
    <div class="leftHeader">
      <img src="${ALL_ROADS_LOGO}" class="logo" />

      <div class="yardTitle">
        YARD TICKET
      </div>
    </div>

    <div class="ticketInfo">
      <div>${copy}</div>
      <div>
        <strong>Ticket # ${ticket.ticket_no || ""}</strong>
      </div>
    </div>
  </div>

  <table>
    <tr>
      <td><strong>Date</strong></td>
      <td>${ticket.ticket_date || ""}</td>
    </tr>

    <tr>
      <td><strong>Customer</strong></td>
      <td>${ticket.customer_name || ""}</td>
    </tr>

    <tr>
      <td><strong>Product</strong></td>
      <td>${ticket.product_name || ""}</td>
    </tr>

    <tr>
      <td><strong>Quantity</strong></td>
      <td>${ticket.quantity || ""} ${ticket.unit || ""}</td>
    </tr>

    <tr>
      <td><strong>Vehicle</strong></td>
      <td>${ticket.license_plate || ""}</td>
    </tr>

    <tr>
      <td><strong>Order</strong></td>
      <td>${ticket.job_number || ""}</td>
    </tr>

    <tr>
      <td><strong>Address</strong></td>
      <td>${ticket.address || ""}</td>
    </tr>

    <tr>
      <td><strong>Notes</strong></td>
      <td>${ticket.notes || ""}</td>
    </tr>
  </table>

  ${
    ticket.status === "cancelled"
      ? '<div class="void">VOID</div>'
      : ""
  }

</div>
    `
    )
    .join("");

  const win = window.open("", "_blank");

  win.document.write(`
    <html>
      <head>
        <title>Yard Ticket</title>

        <style>
  @page {
    size: letter portrait;
    margin: 0.35in;
  }

  body {
    font-family: Arial, sans-serif;
    margin: 0;
    padding: 0;
    color: #111;
  }

  .ticket {
    border: 2px solid #111;
    padding: 8px;
    height: 3.2in;
    box-sizing: border-box;
    margin-bottom: 0.15in;
    page-break-inside: avoid;
    overflow: hidden;
  }

  .header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 4px;
}

  .logo {
  width: 55px;
  height: auto;
  display: block;
}

  .ticketInfo {
    text-align: right;
    font-size: 12px;
    font-weight: 700;
  }

  h2 {
    margin: 4px 0 6px 0;
    font-size: 14px;
  }

  table {
    width: 100%;
    border-collapse: collapse;
    table-layout: fixed;
    font-size: 12px;
  }

  td {
    border: 1px solid #ccc;
    padding: 4px;
    vertical-align: top;
  }

  td:first-child {
    width: 90px;
    font-weight: 700;
  }

  .void {
    margin-top: 6px;
    color: red;
    font-size: 18px;
    font-weight: bold;
    text-align: center;
  }
</style>
      </head>

      <body>
        ${html}
      </body>
    </html>
  `);

  win.document.close();
  win.focus();
  win.print();
}

  async function loadYardTicketsForPrinting() {
  try {
    setLoadingYardTickets(true);

    const { data, error } = await supabase
      .from("yard_tickets")
      .select("*")
      .gte("ticket_date", startDate)
      .lte("ticket_date", endDate)
      .order("ticket_date", { ascending: false })
      .order("ticket_no", { ascending: false });

    if (error) throw error;

    setYardTickets(data || []);

    if (!data?.length) {
      alert("No yard tickets found for that date range.");
    }
  } catch (err) {
    console.error(err);
    alert(err.message || "Failed to load yard tickets.");
  } finally {
    setLoadingYardTickets(false);
  }
}

  async function exportYardTickets() {
    try {
      const [ticketsRes, customersMasterRes] = await Promise.all([
        supabase
          .from("yard_tickets")
          .select("*")
          .gte("ticket_date", startDate)
          .lte("ticket_date", endDate)
          .order("ticket_date", { ascending: true })
          .order("ticket_no", { ascending: true }),

        supabase
  .from("customers_master")
  .select("customer_id, customer_name, normalized_name")
      ]);

      if (ticketsRes.error) throw ticketsRes.error;
      if (customersMasterRes.error) throw customersMasterRes.error;

      const tickets = ticketsRes.data || [];
      const masterRows = customersMasterRes.data || [];

      if (!tickets.length) {
        alert("No yard tickets found for that date range.");
        return;
      }

      const headers = buildAccountingHeaders();

      const dataRows = tickets.map((ticket) => {
        const productInfo = splitProduct(ticket.product_name);

        const masterCustomer = findCustomerByName(
          ticket.customer_name,
          masterRows
        );

        const customerId =
          ticket.customer_code ||
          masterCustomer?.customer_id ||
          "";

        const officialCustomerName =
          masterCustomer?.customer_name ||
          ticket.customer_name ||
          "";

        return [
          formatExportDate(ticket.ticket_date), // Date
          "902020", // Location
          ticket.ticket_no || "", // Ticket
          formatExportTime(ticket.created_at), // Time
          customerId, // Customer
          officialCustomerName, // Customer Name
          ticket.job_number || "", // Order
          ticket.notes || ticket.address || "", // Description
          productInfo.code, // Product
          productInfo.description, // Product Name
          "", // Carrier Name
          "", // Carrier
          ticket.license_plate || "", // Vehicle
          ticket.license_plate || "", // Vehicle Name
          ticket.quantity || "", // Qty
          ticket.unit || "", // Unit
          "", // Total Price
          "", // Dispatch No.
          "", // Dispatch Date
          "", // Dispatch Load
          ticket.status === "cancelled" ? "VOID" : "NORMAL", // Void
          "", // Material
          "", // Freight
          "", // Other
          "", // Tax
          "", // Zone
          "", // Invoice
          "", // Item No
          "", // Purchase Order
          "", // Gross
          "", // Tare
          "", // Net
          "", // Unit Price
          "", // Freight Rate
          "", // Tax Code
          "", // Freight FOB
          "", // Freight Pay
          ticket.address || "", // Destination
          "", // Destination Description
          "", // Reference Ticket
          "", // Today Loads
          "", // Today Qty
          "", // blank
          "", // Reason
        ];
      });

      validateRows(headers, dataRows);

      downloadCsv(`yard_accounting_export_${startDate}_${endDate}.csv`, [
        headers,
        ...dataRows,
      ]);
    } catch (err) {
      console.error(err);
      alert(err.message || "Failed to export yard tickets.");
    }
  }

  async function exportScaleTickets() {
    try {
      const [ticketsRes, customersMasterRes] = await Promise.all([
        supabase
          .from("scale_tickets")
          .select("*")
          .gte("ticket_date", startDate)
          .lte("ticket_date", endDate)
          .order("ticket_date", { ascending: true })
          .order("ticket_no", { ascending: true }),

        supabase
          .from("customers_master")
          .select("customer_id, customer_name, normalized_name"),
      ]);

      if (ticketsRes.error) throw ticketsRes.error;
      if (customersMasterRes.error) throw customersMasterRes.error;

      const tickets = ticketsRes.data || [];
      const masterRows = customersMasterRes.data || [];

      if (!tickets.length) {
        alert("No scale tickets found for that date range.");
        return;
      }

      const headers = buildAccountingHeaders();

      const dataRows = tickets.map((ticket) => {
        const productInfo = splitProduct(ticket.mix_type);

        const masterCustomer = findCustomerByName(ticket.customer, masterRows);

        const customerId =
          ticket.customer_code ||
          masterCustomer?.customer_id ||
          "";

        const officialCustomerName =
          masterCustomer?.customer_name ||
          ticket.customer ||
          "";

        return [
          formatExportDate(ticket.ticket_date), // Date
          "902020", // Location
          ticket.ticket_no || "", // Ticket
          formatExportTime(ticket.created_at), // Time
          customerId, // Customer
          officialCustomerName, // Customer Name
          ticket.job_number || "", // Order
          ticket.address || "", // Description
          productInfo.code, // Product
          productInfo.description, // Product Name
          "", // Carrier Name
          "", // Carrier
          ticket.license_plate || "", // Vehicle
          ticket.license_plate || "", // Vehicle Name
          ticket.net_tonnes || "", // Qty
          "Metric Ton", // Unit
          "", // Total Price
          "", // Dispatch No.
          "", // Dispatch Date
          "", // Dispatch Load
          ticket.voided ? "VOID" : "NORMAL", // Void
          "", // Material
          "", // Freight
          "", // Other
          "", // Tax
          "", // Zone
          "", // Invoice
          "", // Item No
          ticket.po_number || "", // Purchase Order
          ticket.gross_kg || "", // Gross
          ticket.tare_kg || "", // Tare
          ticket.net_kg || "", // Net
          "", // Unit Price
          "", // Freight Rate
          "", // Tax Code
          "", // Freight FOB
          "", // Freight Pay
          ticket.address || "", // Destination
          "", // Destination Description
          "", // Reference Ticket
          "", // Today Loads
          "", // Today Qty
          "", // blank
          ticket.void_reason || "", // Reason
        ];
      });

      validateRows(headers, dataRows);

      downloadCsv(`scale_accounting_export_${startDate}_${endDate}.csv`, [
        headers,
        ...dataRows,
      ]);
    } catch (err) {
      console.error(err);
      alert(err.message || "Failed to export scale tickets.");
    }
  }

  return (
    <div style={styles.page}>
      <div style={styles.card}>
        <h1 style={styles.title}>Accounting Exports</h1>

        <div style={styles.grid}>
          <div>
            <label style={styles.label}>Start Date</label>
            <input
              type="date"
              value={startDate}
              onChange={(e) => setStartDate(e.target.value)}
              style={styles.input}
            />
          </div>

          <div>
            <label style={styles.label}>End Date</label>
            <input
              type="date"
              value={endDate}
              onChange={(e) => setEndDate(e.target.value)}
              style={styles.input}
            />
          </div>
        </div>

        <div style={styles.section}>
  <h2>Yard Tickets</h2>

  <div style={styles.buttonRow}>
    <button style={styles.button} onClick={exportYardTickets}>
      Export Yard Tickets
    </button>

    <button style={styles.button} onClick={loadYardTicketsForPrinting}>
      {loadingYardTickets ? "Loading..." : "Load Yard Tickets to Print"}
    </button>
  </div>
</div>
{yardTickets.length > 0 && (
  <div style={styles.ticketList}>
    {yardTickets.map((ticket) => (
      <div key={ticket.id || ticket.ticket_no} style={styles.ticketRow}>
        <div>
          <strong>#{ticket.ticket_no}</strong> — {ticket.customer_name} —{" "}
          {ticket.product_name} — {ticket.quantity} {ticket.unit}
        </div>

        <button
          style={styles.smallButton}
          onClick={() => printAccountingYardTicket(ticket)}
        >
          Print Accounting Copy
        </button>
      </div>
    ))}
  </div>
)}
      </div>
    </div>
  );
}

const styles = {
  page: {
    padding: 24,
    maxWidth: 1000,
    margin: "0 auto",
  },

  card: {
    background: "#fff",
    padding: 24,
    borderRadius: 16,
    border: "1px solid #ddd",
  },

  title: {
    marginTop: 0,
    marginBottom: 24,
  },

  grid: {
    display: "grid",
    gridTemplateColumns: "1fr 1fr",
    gap: 16,
    marginBottom: 24,
  },

  label: {
    display: "block",
    marginBottom: 6,
    fontWeight: 700,
  },

  input: {
    width: "100%",
    padding: 10,
    fontSize: 16,
  },

  section: {
    marginTop: 24,
    paddingTop: 24,
    borderTop: "1px solid #ddd",
  },

  button: {
    padding: "12px 18px",
    fontSize: 16,
    fontWeight: 700,
    cursor: "pointer",
  },

  buttonRow: {
  display: "flex",
  gap: 12,
  flexWrap: "wrap",
},

ticketList: {
  marginTop: 16,
  display: "grid",
  gap: 8,
},

ticketRow: {
  display: "flex",
  justifyContent: "space-between",
  alignItems: "center",
  gap: 12,
  padding: 12,
  border: "1px solid #ddd",
  borderRadius: 10,
  background: "#f9fafb",
},

smallButton: {
  padding: "8px 12px",
  fontSize: 14,
  fontWeight: 700,
  cursor: "pointer",
},
};